9	// Sort orders records by path, then text, then id so the on-disk ndjson is
10	// deterministic regardless of insertion order.
11	func Sort(records []Record) {
12		sort.Slice(records, func(i, j int) bool {
13			li, lj := strings.Join(records[i].Paths, ","), strings.Join(records[j].Paths, ",")
14			if li != lj {
15				return li < lj
16			}
17			if records[i].Text != records[j].Text {
18				return records[i].Text < records[j].Text
19			}
20			return records[i].ID < records[j].ID
21		})
22	}
