278	// Prefer the output terminal. Entire may pipe plugin output, so also consult
279	// the controlling terminal for file-backed output. Unknown width means no wrap.
280	func helpTerminalWidth(out io.Writer) int {
281		if f, ok := out.(interface{ Fd() uintptr }); ok {
282			if width, _, err := term.GetSize(f.Fd()); err == nil && width > 0 {
283				return width
284			}
285			if tty, err := os.Open("/dev/tty"); err == nil {
286				defer tty.Close()
287				if width, _, err := term.GetSize(tty.Fd()); err == nil && width > 0 {
288					return width
289				}
290			}
291		}
292		if width, err := strconv.Atoi(os.Getenv("COLUMNS")); err == nil && width > 0 {
293			return width
294		}
295		return 0
296	}
