298	func writeHelpCommand(out io.Writer, name, description string, nameWidth, terminalWidth int) {
299		indent := nameWidth + 4
300		prefix := fmt.Sprintf("  %-*s  ", nameWidth, name)
301		if terminalWidth <= 0 || ansi.StringWidth(prefix+description) <= terminalWidth {
302			fmt.Fprintln(out, prefix+description)
303			return
304		}
305		// On very narrow terminals, put the description below the command name.
306		if terminalWidth <= indent {
307			fmt.Fprintf(out, "  %s\n", name)
308			indent = min(2, max(0, terminalWidth-1))
309			prefix = strings.Repeat(" ", indent)
310		}
311		wrapped := ansi.Wrap(description, max(1, terminalWidth-indent), "")
312		fmt.Fprintln(out, prefix+strings.ReplaceAll(wrapped, "\n", "\n"+strings.Repeat(" ", indent)))
313	}
