351	func wrapJSONErrorRendering(cmd *cobra.Command) {
352		if cmd.Args != nil {
353			argsFunc := cmd.Args
354			cmd.Args = func(cmd *cobra.Command, args []string) error {
355				err := argsFunc(cmd, args)
356				if err == nil || !commandWantsJSONError(cmd) {
