421	func commandFormatFlagWantsJSON(value string) (bool, bool) {
422		switch strings.ToLower(strings.TrimSpace(value)) {
423		case "json":
424			return true, true
425		case "cli":
426			return false, true
427		default:
428			return false, false
429		}
430	}
