432	func commandRawFormatWantsJSON(args []string) (bool, bool) {
433		for i, arg := range args {
434			if arg == "--format" {
435				if i+1 >= len(args) {
436					return false, false
437				}
438				return commandFormatFlagWantsJSON(args[i+1])
439			}
440			if strings.HasPrefix(arg, "--format=") {
441				return commandFormatFlagWantsJSON(strings.TrimPrefix(arg, "--format="))
442			}
443		}
444		return false, false
445	}
446	
447	func commandJSONFlagEnabled(value string) bool {
448		value = strings.ToLower(value)
449		return value != "false" && value != "0"
450	}
