452	func commandRawArgs(cmd *cobra.Command) []string {
453		root := cmd.Root()
454		if root == nil {
455			return os.Args[1:]
456		}
457		value := reflect.ValueOf(root)
458		if value.Kind() != reflect.Pointer || value.IsNil() {
459			return os.Args[1:]
460		}
461		args := value.Elem().FieldByName("args")
462		if !args.IsValid() || args.Kind() != reflect.Slice || args.IsNil() {
463			return os.Args[1:]
464		}
465		out := make([]string, 0, args.Len())
466		for i := 0; i < args.Len(); i++ {
467			out = append(out, args.Index(i).String())
468		}
469		return out
470	}
