487	func commandErrorCode(err error) string {
488		message := err.Error()
489		code, _, ok := strings.Cut(message, ":")
490		if ok {
491			code = strings.TrimSpace(code)
492			if commandErrorCodePattern.MatchString(code) {
493				return code
494			}
495		}
496		return "command_failed"
497	}
